const tabId = 1962625065;
console.log(await browserjs(tabId, async () => {
  const queries = ['charity', 'charitable', 'charity+foundations', 'non+profit'];
  const allResults = {};

  for (const q of queries) {
    const url = `https://www.bbb.org/search?find_country=USA&find_latlng=42.598241%2C-74.154146&find_loc=12023&find_text=${q}&filter_accredited=1`;
    const resp = await fetch(url);
    const html = await resp.text();

    // parse html
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    const cards = Array.from(doc.querySelectorAll('.result-card, [class*="result-card"]'));
    allResults[q] = cards.map(c => {
      const h3 = c.querySelector('h3');
      const rating = c.innerText.match(/BBB Rating:\s*([A-F][+-]?)/)?.[1] || "None";
      const paragraphs = Array.from(c.querySelectorAll('p')).map(p => p.innerText.trim());
      return {
        title: h3?.innerText.trim(),
        rating,
        categories: paragraphs[0] || "",
        location: paragraphs[1] || "",
        text: c.innerText.replace(/\n+/g, ' ').slice(0, 200)
      };
    });
  }
  return allResults;
}));

