const tabId = 1962625065;
console.log(await browserjs(tabId, async () => {
  // Let's test searching for categories on BBB by looking at the search page Category facet
  // Go back to the search page for charity near 12023
  // Let's see what category names exist on BBB by checking common ones
  const testCategories = [
    'charity',
    'charities',
    'charity-foundations',
    'charity-local',
    'non-profit-organizations',
    'nonprofit',
    'philanthropic-foundations',
    'social-service-organizations',
    'human-services-organizations',
    'volunteer-organizations',
    'association'
  ];

  const results = {};
  for (const cat of testCategories) {
    try {
      const resp = await fetch(`https://www.bbb.org/us/ny/south-berne/category/${cat}`, { method: 'HEAD' });
      results[cat] = resp.status;
    } catch (e) {
      results[cat] = e.message;
    }
  }
  return results;
}));

